                min_c, max_c = min(cell[1] for cell in cells), max(cell[1] for cell in cells)
                objects.append((min_r, max_r, min_c, max_c))

    # Fill the corridor between semua objects with color 3
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == object_color:
                continue
            if result[r][c] != 0 and result[r][c] != background_color:
                # Already colored
                continue

            col_obj = False
            # Check if this column is aligned with any object
            for (o_min_r, o_max_r, o_min_c, o_max_c) in objects:
                if o_min_c <= c <= o_max_c:
                    col_obj = True
                    break

            if col_obj:
                # Check if this column should be colored
                row_obj = False
                for (o_min_r, o_max_r, o_min_c, o_max_c) in objects:
                    if o_min_r <= r <= o_max_r:
                        row_obj = True
                        break

                # If vertically aligned with object but not currently an object
                if row_obj and r != min_r and r != max_r:
                    result[r][c] = 3

    # Add bottom color 1 blocks for each object
    for (min_r, max_r, min_c, max_c) in objects:
        # Height of object
        h = max_r - min_r + 1
        top_pad = h // 2

        # Color 1 extends from bottom of object
        start_row = max_r + top_pad + 1
        for r in range(start_row, min(start_row + h, rows)):
            for c in range(min_c, max_c + 1):
                if result[r][c] == background_color:
                    result[r][c] = 1

    return result
