```python
def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    from collections import Counter
    color_counts = Counter()
    for r in range(rows):
        for c in range(cols):
            color_counts[grid[r][c]] += 1

    background_color = max(color_counts, key=color_counts.get)
    object_color = [c for c in color_counts if c != background_color][0]

    result = [row[:] for row in grid]

    # Find all connected objects
    visited = set()
    objects = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == object_color and (r, c) not in visited:
                cells = []
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    curr_r, curr_c = stack.pop()
                    cells.append((curr_r, curr_c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r+dr, curr_c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == object_color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                min_r = min(x[0] for x in cells)
                max_r = max(x[0] for x in cells)
                min_c = min(x[1] for x in cells)
                max_c = max(x[1] for x in cells)
                h = max_r - min_r + 1
                w = max_c - min_c + 1
                pad_w = w // 2
                pad_h = h // 2
                objects.append((min_r, max_r, min_c, max_c, h, w, pad_w, pad_h))

    # Apply decorations based on Demo 2 pattern
    for obj in objects:
        min_r, max_r, min_c, max_c = obj[:4]
        h, w, pad_w, pad_h = obj[4:]

        # Top cap (color 3)
        for r in range(min_r - pad_h, min_r):
            if r >= 0:
                for c in range(min_c - pad_w, max_c + pad_w + 1):
                    if 0 <= c < cols and (r, c) not in [(cell[0], cell[1]) for cell in []]:
                        result[r][c] = 3

        # Side shields (color 3)
        for r in range(min_r, max_r + 1):
            for c in range(min_c - pad_w, min_c):
                if 0 <= c < cols:
                    result[r][c] = 3
            for c in range(max_c + 1, max_c + pad_w + 1):
                if 0 <= c < cols:
                    result[r][c] = 3

        # Bottom cap (color 3)
        for r in range(max_r + 1, max_r + pad_h + 1):
            if r < rows:
                for c in range(min_c - pad_w, max_c + pad_w + 1):
                    if 0 <= c < cols:
                        result[r][c] = 3

        # Bottom extension (color 1)
        for r in range(max_r + pad_h + 1, max_r + pad_h + 1 + h):
            if r < rows:
                for c in range(min_c, max_c + 1):
                    if result[r][c] == background_color:
                        result[r][c] = 1

    return result
